105| * @example KNOWN_SECTION_HISTORY.includes('how-it-works') => true
106| ***/
107|export const KNOWN_SECTION_HISTORY = [
108|	"getting-started",
109|	"concepts",
110|	"workflows",
111|	"reference",
112|	"how-it-works",
113|	"working-with",
