116|/***
117| * MARK: SLUG_PATTERN
118| * @description Strict allowlist for article slugs. Only lowercase alphanumerics
119| *   and single hyphens — this makes path traversal impossible by construction.
120| * @example SLUG_PATTERN.test('my-article') => true
121| ***/
122|export const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
123|
124|/***
125| * MARK: isValidSlug
126| * @description Whether a slug is safe to resolve to a content file.
127| * @param {string} slug
128| * @returns {boolean}
129| * @example isValidSlug('../secret') => false
130| ***/
131|export function isValidSlug(slug) {
132|	return typeof slug === "string" && SLUG_PATTERN.test(slug);
133|}
