135|/***
136| * MARK: defaultDocsDir
137| * @description Resolves the content directory: explicit override (tests),
138| *   else the validated `KAINBAIN_SITE_DOCS` config (default
139| *   `<repo-root>/site-docs`).
140| * @param {string} [contentDirectoryOverride]
141| * @returns {string}
142| * @example defaultDocsDir() => '/home/[REDACTED]/kainbain/site-docs'
143| ***/
144|export function defaultDocsDir(contentDirectoryOverride) {
145|	if (contentDirectoryOverride) return contentDirectoryOverride;
146|	return config.siteDocsDir;
147|}
