200|/***
201| * MARK: warnUnlessFileMissing
202| * @description Emits one owner-facing warning for a filesystem failure unless
203| *   the path simply does not exist (ENOENT), which callers treat as a normal
204| *   empty/miss signal: `getDoc` probes `${slug}.md` directly, and `listDocs`
205| *   on a missing dir means "no content", so those stay silent while genuine
206| *   problems (permissions, not-a-directory, I/O errors) stay loud.
207| * @param {object} inputs - Labelled inputs.
208| * @param {unknown} inputs.fileSystemError - The caught error.
209| * @param {string} inputs.warningMessage - Message to emit when not ENOENT.
210| * @returns {void}
211| * @example warnUnlessFileMissing({ fileSystemError: caughtError, warningMessage: '[siteDocs] ...' })
212| ***/
213|function warnUnlessFileMissing({ fileSystemError, warningMessage }) {
214|	if (fileSystemError?.code !== "ENOENT") {
215|		console.warn(warningMessage);
216|	}
217|}
218|
219|/***
220| * MARK: readDocFile
221| * @description Reads one article file into a descriptor, or null when the file
222| *   cannot be used. Loud vs silent nulls — every section-caused skip warns so
223| *   custom content can never silently vanish again:
224| *   - retired `section:` with an alias: resolves to the new section and warns
225| *     once naming the file, the retired id, and the replacement.
226| *   - retired `section:` with NO alias (a rename shipped without its mapping):
227| *     returns null and warns loudly naming the retired id and the fix.
228| *   - unknown or missing `section:`: returns null and warns naming the file.
229| *   - missing file (ENOENT): returns null silently — `getDoc` probes
230| *     `${slug}.md` directly, so a miss is a normal control-flow signal.
231| *   - unreadable file for any other reason (permissions, ...): returns null
232| *     and warns naming the file and the error code.
233| *   - missing title or invalid slug: returns null silently (unchanged
234| *     authoring-error behavior; outside the section-rename scope).
235| * @param {string} filePath - Absolute path to the `.md` file.
236| * @returns {object|null} { slug, title, section, order, markdown } or null.
237| * @example readDocFile('/x/site-docs/architecture.md') => { slug: 'architecture', ... }
238| ***/
239|export function readDocFile(filePath) {
240|	let rawFileContent;
241|	try {
242|		/* eslint-disable security/detect-non-literal-fs-filename */
243|		rawFileContent = fs.readFileSync(filePath, "utf8");
244|		/* eslint-enable security/detect-non-literal-fs-filename */
245|	} catch (fileReadError) {
246|		warnUnlessFileMissing({
247|			fileSystemError: fileReadError,
248|			warningMessage: `[siteDocs] Could not read ${path.basename(String(filePath))} (${fileReadError?.code ?? "unknown error"}) — article skipped from the index.`,
249|		});
250|		return null;
251|	}
252|	const { meta, body } = parseFrontmatter(rawFileContent);
253|	const fallbackSlug = path.basename(filePath, ".md").toLowerCase();
254|	const slug = (meta.slug || fallbackSlug).toLowerCase();
255|	const title = (meta.title || "").trim();
256|	const rawSection = (meta.section || "").trim();
257|	const order = Number.parseInt(meta.order, 10);
258|	if (!isValidSlug(slug)) return null;
259|	if (!title) return null;
260|	const { resolvedSectionName, retiredSectionId } = resolveSectionName({
261|		rawSectionName: rawSection,
262|	});
263|	if (retiredSectionId) {
264|		console.warn(
265|			`[siteDocs] ${path.basename(filePath)} uses retired section "${retiredSectionId}"; resolved to "${resolvedSectionName}". Update frontmatter to "section: ${resolvedSectionName}".`,
266|		);
267|	}
268|	if (!resolvedSectionName) {
269|		if (KNOWN_SECTION_HISTORY.includes(rawSection)) {
270|			console.warn(
271|				`[siteDocs] ${path.basename(filePath)} uses retired section "${rawSection}" which has no LEGACY_SECTION_ALIASES entry — article skipped from the index. This is an upgrade break: add LEGACY_SECTION_ALIASES['${rawSection}'] = '<new-section>' plus a DEPRECATIONS.md entry; see the REQUIRED RENAME PROCEDURE on DOC_SECTIONS in api/siteDocs.js.`,
272|			);
273|		} else if (rawSection) {
274|			console.warn(
275|				`[siteDocs] ${path.basename(filePath)} has unknown section "${rawSection}" — article skipped from the index. Use one of: ${DOC_SECTIONS.join(", ")}.`,
276|			);
277|		} else {
278|			console.warn(
279|				`[siteDocs] ${path.basename(filePath)} has no "section:" frontmatter — article skipped from the index. Add "section:" with one of: ${DOC_SECTIONS.join(", ")}.`,
280|			);
281|		}
282|		return null;
283|	}
284|	return {
285|		slug,
286|		title,
287|		section: resolvedSectionName,
288|		order: Number.isFinite(order) ? order : 999,
289|		markdown: body.trimStart(),
290|	};
291|}
292|
293|/***
294| * MARK: listDocs
295| * @description Builds the docs index from frontmatter: `[{ slug, title,
296| *   section, order }]`, ordered by section group then `order` then title.
297| *   Files with invalid frontmatter are skipped so one bad article cannot
298| *   break the index — and every section-caused skip warns via `readDocFile`,
299| *   so the skip is loud, not hidden. A missing directory returns [] silently
300| *   (no content is a normal state); an unreadable directory returns [] with
301| *   a warning naming the directory and the error code.
302| * @param {object} [options]
303| * @param {string} [options.dir] - Content directory override (tests).
304| * @returns {Array<object>}
305| * @example listDocs() => [{ slug: 'architecture', section: 'concepts', ... }]
306| ***/
307|export function listDocs({ dir } = {}) {
308|	const docsDir = defaultDocsDir(dir);
309|	let directoryEntries;
310|	try {
311|		/* eslint-disable security/detect-non-literal-fs-filename */
312|		directoryEntries = fs.readdirSync(docsDir, { withFileTypes: true });
313|		/* eslint-enable security/detect-non-literal-fs-filename */
314|	} catch (directoryReadError) {
315|		warnUnlessFileMissing({
316|			fileSystemError: directoryReadError,
317|			warningMessage: `[siteDocs] Could not read docs directory ${docsDir} (${directoryReadError?.code ?? "unknown error"}) — returning an empty index.`,
318|		});
319|		return [];
320|	}
321|	const sectionRankById = Object.fromEntries(
322|		DOC_SECTIONS.map((sectionId, sectionIndex) => [sectionId, sectionIndex]),
323|	);
324|	const indexedArticles = [];
325|	for (const directoryEntry of directoryEntries) {
326|		if (!directoryEntry.isFile() || !directoryEntry.name.endsWith(".md")) continue;
327|		if (directoryEntry.name.toLowerCase() === "readme.md") continue;
328|		const articleDescriptor = readDocFile(path.join(docsDir, directoryEntry.name));
329|		if (articleDescriptor) indexedArticles.push(articleDescriptor);
330|	}
331|	// De-duplicate on slug: first file wins (sorted by filename for stability).
332|	indexedArticles.sort((firstArticle, secondArticle) =>
333|		firstArticle.slug.localeCompare(secondArticle.slug),
334|	);
335|	const seenSlugs = new Set();
336|	const uniqueArticles = indexedArticles.filter((articleDescriptor) => {
337|		if (seenSlugs.has(articleDescriptor.slug)) return false;
338|		seenSlugs.add(articleDescriptor.slug);
339|		return true;
340|	});
341|	uniqueArticles.sort((firstArticle, secondArticle) => {
342|		const sectionDiff =
343|			(sectionRankById[firstArticle.section] ?? 99) - (sectionRankById[secondArticle.section] ?? 99);
344|		if (sectionDiff !== 0) return sectionDiff;
345|		if (firstArticle.order !== secondArticle.order) return firstArticle.order - secondArticle.order;
346|		return firstArticle.title.localeCompare(secondArticle.title);
347|	});
348|	return uniqueArticles.map(({ slug, title, section, order }) => ({ slug, title, section, order }));
349|}
350|
351|/***
352| * MARK: getDoc
353| * @description Returns one article `{ slug, title, section, order, markdown }`
354| *   or null for invalid slugs / unknown articles. Slug-gated (never joins a
355| *   raw user path), so traversal attempts 404 instead of escaping the dir.
356| * @param {string} slug
357| * @param {object} [options]
358| * @param {string} [options.dir] - Content directory override (tests).
359| * @returns {object|null}
360| * @example getDoc('architecture') => { slug: 'architecture', markdown: '# ...' }
361| ***/
362|export function getDoc(slug, { dir } = {}) {
363|	if (!isValidSlug(slug)) return null;
364|	const docsDir = defaultDocsDir(dir);
365|	const indexEntries = listDocs({ dir: docsDir });
366|	const matchingEntry = indexEntries.find((indexEntry) => indexEntry.slug === slug);
367|	if (!matchingEntry) return null;
368|	const articleFromDirectRead = readDocFile(path.join(docsDir, `${slug}.md`));
369|	if (articleFromDirectRead) return articleFromDirectRead;
370|	// Slug came from frontmatter of a differently-named file: find it by scan.
371|	let directoryEntries;
372|	try {
373|		/* eslint-disable security/detect-non-literal-fs-filename */
374|		directoryEntries = fs.readdirSync(docsDir, { withFileTypes: true });
375|		/* eslint-enable security/detect-non-literal-fs-filename */
376|	} catch (directoryReadError) {
377|		warnUnlessFileMissing({
378|			fileSystemError: directoryReadError,
379|			warningMessage: `[siteDocs] Could not re-read docs directory ${docsDir} (${directoryReadError?.code ?? "unknown error"}) while resolving slug "${slug}".`,
380|		});
381|		return null;
382|	}
383|	for (const directoryEntry of directoryEntries) {
384|		if (!directoryEntry.isFile() || !directoryEntry.name.endsWith(".md")) continue;
385|		const articleDescriptor = readDocFile(path.join(docsDir, directoryEntry.name));
386|		if (articleDescriptor && articleDescriptor.slug === slug) return articleDescriptor;
387|	}
388|	return null;
389|}
390|
391|/***
392| * MARK: buildDocsIndex
393| * @description Builds the full `GET /docs` index payload from the single
394| *   taxonomy source: `sections` is a copy of `DOC_SECTIONS` (sidebar order),
395| *   `sectionLabels` is a copy of `SECTION_LABELS`, and `docs` is the
396| *   `listDocs` article index. The frontend derives its sidebar order and
397| *   group labels from this payload, so a rename edits `DOC_SECTIONS` /
398| *   `SECTION_LABELS` here and nothing else — there is no second copy.
399| * @param {object} [options]
400| * @param {string} [options.dir] - Content directory override (tests).
401| * @returns {{ sections: string[], sectionLabels: object, docs: Array<object> }}
402| * @example buildDocsIndex().sections => [...DOC_SECTIONS]
403| ***/
404|export function buildDocsIndex({ dir } = {}) {
405|	return {
406|		sections: [...DOC_SECTIONS],
407|		sectionLabels: { ...SECTION_LABELS },
408|		docs: listDocs({ dir }),
409|	};
410|}

