149|/***
150| * MARK: parseFrontmatter
151| * @description Splits a raw article file into `{ meta, body }`. Returns empty
152| *   meta when no `---` frontmatter block is present.
153| * @param {string} rawFileContent - Full file content.
154| * @returns {{ meta: object, body: string }}
155| * @example parseFrontmatter('---\ntitle: Hi\n---\nBody') => { meta: { title: 'Hi' }, body: 'Body' }
156| ***/
157|export function parseFrontmatter(rawFileContent) {
158|	const fileContentText = String(rawFileContent ?? "");
159|	const frontmatterMatch = fileContentText.match(/^---\s*\r?\n([\s\S]*?)\r?\n---\s*(?:\r?\n|$)/);
160|	if (!frontmatterMatch) return { meta: {}, body: fileContentText };
161|	const meta = {};
162|	for (const line of frontmatterMatch[1].split(/\r?\n/)) {
163|		const separatorIndex = line.indexOf(":");
164|		if (separatorIndex === -1) continue;
165|		const frontmatterKey = line.slice(0, separatorIndex).trim();
166|		const frontmatterValue = line.slice(separatorIndex + 1).trim();
167|		if (frontmatterKey) meta[frontmatterKey] = frontmatterValue;
168|	}
169|	return { meta, body: fileContentText.slice(frontmatterMatch[0].length) };
170|}
