172|/***
173| * MARK: resolveSectionName
174| * @description Maps one raw `section:` frontmatter value to the section id to
175| *   index under. Pure lookup with no logging: current ids pass through,
176| *   retired ids resolve through `LEGACY_SECTION_ALIASES`, and anything else
177| *   resolves to null so the caller can skip the file loudly. Uses an
178| *   own-property check so object-prototype names (`__proto__`, `toString`,
179| *   ...) can never mis-resolve to an alias entry.
180| * @param {object} [inputs] - Labelled inputs.
181| * @param {string} [inputs.rawSectionName] - The raw frontmatter value.
182| * @returns {{ resolvedSectionName: string|null, retiredSectionId: string|null }} The id to index under (null when unresolvable) plus the retired id when an alias applied.
183| * @example resolveSectionName({ rawSectionName: 'how-it-works' }) => { resolvedSectionName: 'concepts', retiredSectionId: 'how-it-works' }
184| ***/
185|export function resolveSectionName({ rawSectionName } = {}) {
186|	const trimmedSectionName = String(rawSectionName ?? "").trim();
187|	if (DOC_SECTIONS.includes(trimmedSectionName)) {
188|		return { resolvedSectionName: trimmedSectionName, retiredSectionId: null };
189|	}
190|	if (Object.hasOwn(LEGACY_SECTION_ALIASES, trimmedSectionName)) {
191|		return {
192|			/* eslint-disable-next-line security/detect-object-injection -- key is hasOwn-checked on the line above */
193|			resolvedSectionName: LEGACY_SECTION_ALIASES[trimmedSectionName],
194|			retiredSectionId: trimmedSectionName,
195|		};
196|	}
197|	return { resolvedSectionName: null, retiredSectionId: null };
198|}
