363|	if (!isValidSlug(slug)) return null;
364|	const docsDir = defaultDocsDir(dir);
365|	const indexEntries = listDocs({ dir: docsDir });
366|	const matchingEntry = indexEntries.find((indexEntry) => indexEntry.slug === slug);
367|	if (!matchingEntry) return null;
368|	const articleFromDirectRead = readDocFile(path.join(docsDir, `${slug}.md`));
