16| * @example deriveSectionOrder({ index: { sections: ['b', 'a'] }, docs: [] }) => ['b', 'a']
17| ***/
18|export function deriveSectionOrder({ index, docs } = {}) {
19|  const fromIndex = [];
20|  const indexSections = Array.isArray(index?.sections) ? index.sections : [];
21|  for (const entry of indexSections) {
22|    if (typeof entry === 'string' && entry.length > 0 && !fromIndex.includes(entry)) {
23|      fromIndex.push(entry);
24|    }
25|  }
